 function astrocyte({coverage=.75,transport=1,synthetase=1,frequency=20,pulses=4,total=120,dt=.001}={}){check(coverage,0,1);check(transport,0,1);check(synthetase,0,1);check(frequency,5,50);check(pulses,1,8);check(total,2,180);check(dt,.0005,.002);if(!Number.isInteger(pulses))throw Error('Число стимулов должно быть целым');const times=Array.from({length:pulses},(_,i)=>1+i/frequency),trace=[];let next=0,g=0,ag=0,aq=0,eq=0,nq=0,v=100,escaped=0,uptakeTotal=0,peak=0;for(let i=0;i<=Math.round(total/dt);i++){const t=i*dt;if(next<times.length&&t+dt/2>=times[next]){const released=.15*v;v-=released;g+=released;next++;}const uptake=Math.min(g,1000*coverage*transport*g/(2+g)*dt),escape=Math.min(g-uptake,2*g*dt),convert=Math.min(ag,synthetase*ag/20*dt),exportQ=Math.min(aq,aq/10*dt),importQ=Math.min(eq,eq/15*dt),recycle=Math.min(nq,nq/15*dt);if((t<2&&i%Math.max(1,Math.round(.001/dt))===0)||(t>=2&&i%Math.max(1,Math.round(.1/dt))===0))trace.push({t,cleft:g,astroG:ag,astroQ:aq,extraQ:eq,neuronQ:nq,vesicles:v,escaped,uptake:uptake/dt,convert:convert/dt,recycle:recycle/dt});g-=uptake+escape;ag+=uptake-convert;aq+=convert-exportQ;eq+=exportQ-importQ;nq+=importQ-recycle;v+=recycle;escaped+=escape;uptakeTotal+=uptake;peak=Math.max(peak,g);}const balance=g+ag+aq+eq+nq+v+escaped-100;return{trace,times,total,balance,uptakeTotal,peak,final:{cleft:g,astroG:ag,astroQ:aq,extraQ:eq,neuronQ:nq,vesicles:v,escaped},units:'seconds; relative amounts, illustrative rates',parameters:{coverage,transport,synthetase,frequency,pulses}};}
 function basal({input=.7,dopamine=.6,d1=1,d2=1,hyperdirect=true,dt=.2,total=1000}={}){check(input,0,1);check(dopamine,0,1);check(d1,0,1);check(d2,0,1);check(dt,.05,.5);check(total,400,2000);let state=[.1,.1,.5,.3,.5,.2];const trace=[],keys=['d1','d2','gpe','stn','gpi','thalamus'];function targets(s,c){const[a,b,p,n,o]=s;return[sigmoid(4*(c*(1+.7*dopamine*d1)-.4)),sigmoid(4*(c*(1-.65*dopamine*d2)-.4)),sigmoid(1.3-2.4*b+.7*n),sigmoid(.8+(hyperdirect?1.8*c:0)-2.2*p),sigmoid(1.2+2.1*n-2.5*a-.35*p),sigmoid(.7+1.3*c-3.2*o)];}for(let i=0;i<Math.round(500/dt);i++){const target=targets(state,.1);state=state.map((v,k)=>v+dt/25*(target[k]-v));}for(let i=0;i<=Math.round(total/dt);i++){const t=i*dt,c=t>=100&&t<700?input:.1,target=targets(state,c);if(i%Math.max(1,Math.round(2/dt))===0)trace.push({t,input:c,...Object.fromEntries(keys.map((k,j)=>[k,state[j]]))});state=state.map((v,k)=>v+dt/25*(target[k]-v));}return{trace,total,keys,plateau:trace.reduce((a,b)=>Math.abs(b.t-600)<Math.abs(a.t-600)?b:a),units:'ms; normalized population activity',parameters:{input,dopamine,d1,d2,hyperdirect}};}
 function sample(trace,time){check(time,-1e6,1e6);if(!trace.length)throw Error('Пустая трасса');let a=0,b=trace.length-1;while(a<b){const m=(a+b)>>1;if(trace[m].t<time)a=m+1;else b=m;}return a&&Math.abs(trace[a-1].t-time)<Math.abs(trace[a].t-time)?trace[a-1]:trace[a];}
